import {gunzipSync,strFromU8} from 'fflate';
import type {DomainEvent,V4State} from './model.ts';
/** Finite exact production observations issued before paid overtime existed.
 * Generated from the 33 committed campaign-native artifacts at 44f5d6f.
 * No new tick or modified production copy can use this compatibility boundary.
 * Paid staff capacity continues to be independently reconstructed for every close. */
const packed="";
let issued:Record<string,{week:number;signature:string;production:string}[]>|undefined;
export function legacyLaborClose(event:DomainEvent,production:V4State['snapshots'][number]['production']){
 if(event.details.overtimeActuals!==undefined)return false;
 issued??=JSON.parse(strFromU8(gunzipSync(Uint8Array.from(atob(packed),c=>c.charCodeAt(0)))));
 return (issued![event.id]??[]).some(v=>v.week===event.week&&v.signature===event.signature&&v.production===JSON.stringify(production));
}
